import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

// issue #12: 1,000 x (1 - 0.1) = 900. The customer discount applies once.
test('total applies the customer discount once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

// issue #12: 10 lines, subtotal 10,000 -> 10,000 x 0.9 = 9,000 -> 9,000 x 0.95 = 8,550.
test('total applies the bulk discount once, after the customer discount', () => {
  const items = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(items, 0.1), 8550);
});

// issue #12: with a discount rate of 0 the total stays as before: 10,000 x 0.95 = 9,500.
test('total with a zero discount rate still gets the bulk discount only', () => {
  const items = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(items, 0), 9500);
  assert.equal(total(items), 9500);
});

// Bulk discount boundary: 9 lines get the customer discount only: 9,000 x 0.9 = 8,100.
test('total with fewer than 10 lines gets no bulk discount', () => {
  const items = Array.from({ length: 9 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(items, 0.1), 8100);
});
